"""Tool-level guardrails for ARC's staged agent workflow."""

from __future__ import annotations

from typing import Any, Literal, NotRequired, TypedDict

from langchain.agents.middleware.types import AgentMiddleware, ToolCallRequest
from langchain_core.messages import ToolMessage

_FILE_WRITE_TOOLS = frozenset({"edit_file", "write_file"})
_VALIDATION_TOOLS = frozenset({"run_build", "run_tests"})
_MAX_DESIGN_WRITES = 8
_MAX_SKELETON_LINES = 160
_MAX_READ_LIMIT = 200


class StageDisciplineState(TypedDict, total=False):
    """Run-local state used to prevent redundant file-tool loops."""

    arc_read_summaries: NotRequired[dict[str, str]]
    arc_written_paths: NotRequired[list[str]]


class StageDisciplineMiddleware(AgentMiddleware[StageDisciplineState, Any, Any]):
    """Enforce stage boundaries and stop post-write self-review loops."""

    state_schema = StageDisciplineState

    def __init__(self, *, stage: Literal["interface_design", "test_generation", "implementation"]) -> None:
        self._stage = stage
        self._read_ranges: dict[str, list[tuple[int, int]]] = {}
        self._written_paths: set[str] = set()
        self._failed_paths: set[str] = set()
        self._validation_failed = False
        self._design_write_count = 0

    def wrap_tool_call(self, request: ToolCallRequest, handler: Any) -> ToolMessage | Any:
        blocked = self._validate_tool_call(request)
        if blocked:
            return self._blocked(request, blocked)
        request = self._with_bounded_read(request)
        result = handler(request)
        self._record_result(request, result)
        return result

    async def awrap_tool_call(self, request: ToolCallRequest, handler: Any) -> ToolMessage | Any:
        blocked = self._validate_tool_call(request)
        if blocked:
            return self._blocked(request, blocked)
        request = self._with_bounded_read(request)
        result = await handler(request)
        self._record_result(request, result)
        return result

    def _validate_tool_call(self, request: ToolCallRequest) -> str | None:
        name = str(request.tool_call.get("name", ""))
        args = request.tool_call.get("args", {}) or {}
        if name in {"execute", "delete"}:
            return f"`{name}` is disabled in ARC's staged file workflow."
        if self._stage == "test_generation" and name in _VALIDATION_TOOLS:
            return "TestGenerator only creates tests and its manifest; it must not run validation."
        if name == "read_file":
            return self._validate_read(args)
        if name in _FILE_WRITE_TOOLS:
            return self._validate_write(args)
        return None

    def _validate_read(self, args: dict[str, Any]) -> str | None:
        path = _discipline_path(args)
        if not path:
            return None
        if path in self._written_paths and not self._path_unlocked(path):
            return (
                f"Read blocked: {path} was already written in this stage. Continue to the next action; "
                "re-read only after a file-operation or system-validation error."
            )
        offset = _as_nonnegative_int(args.get("offset"), default=0)
        limit = min(_as_nonnegative_int(args.get("limit"), default=100), _MAX_READ_LIMIT)
        previous = self._read_ranges.get(path, [])
        if not previous or self._path_unlocked(path):
            return None
        if any(_ranges_overlap(offset, offset + limit, start, end) for start, end in previous):
            return (
                f"Repeated read blocked: {path} is already in this stage's read cache. "
                "Use the earlier result; only a non-overlapping paginated range or a failure may justify another read."
            )
        return None

    def _validate_write(self, args: dict[str, Any]) -> str | None:
        path = _discipline_path(args)
        if not path:
            return None
        if path in self._written_paths and not self._path_unlocked(path):
            return (
                f"Repeated write blocked: {path} was already changed in this stage. "
                "Wait for a file-operation or system-validation error before changing it again."
            )
        if self._stage == "test_generation" and not _is_test_asset(path):
            return (
                "TestGenerator may write only test files, test helpers/configuration, and the returned manifest; "
                f"{path} is not a test asset."
            )
        if self._stage == "interface_design":
            if path not in self._written_paths and self._design_write_count >= _MAX_DESIGN_WRITES:
                return (
                    f"InterfaceDesigner may materialize at most {_MAX_DESIGN_WRITES} small skeleton files. "
                    "Record remaining interfaces in the response for TDD."
                )
            content = str(args.get("content", args.get("new_string", "")) or "")
            if content.count("\n") + 1 > _MAX_SKELETON_LINES:
                return (
                    f"InterfaceDesigner may only materialize small skeletons (at most {_MAX_SKELETON_LINES} lines per write). "
                    "Record the complete business contract for TDD instead of implementing it now."
                )
        return None

    def _with_bounded_read(self, request: ToolCallRequest) -> ToolCallRequest:
        if request.tool_call.get("name") != "read_file":
            return request
        args = dict(request.tool_call.get("args", {}) or {})
        if not _discipline_path(args).startswith("/workspace/"):
            return request
        args["offset"] = _as_nonnegative_int(args.get("offset"), default=0)
        args["limit"] = min(_as_nonnegative_int(args.get("limit"), default=100), _MAX_READ_LIMIT)
        return request.override(tool_call={**request.tool_call, "args": args})

    def _record_result(self, request: ToolCallRequest, result: ToolMessage | Any) -> None:
        name = str(request.tool_call.get("name", ""))
        args = request.tool_call.get("args", {}) or {}
        path = _discipline_path(args)
        if name in _VALIDATION_TOOLS:
            if _tool_result_failed(result):
                self._validation_failed = True
                self._failed_paths.update(self._written_paths)
            return
        if _tool_result_failed(result):
            if path:
                self._failed_paths.add(path)
            return
        if name == "read_file" and path:
            offset = _as_nonnegative_int(args.get("offset"), default=0)
            limit = _as_nonnegative_int(args.get("limit"), default=100)
            self._read_ranges.setdefault(path, []).append((offset, offset + limit))
            self._cache_read_summary(request, path, offset, limit, result)
        if name in _FILE_WRITE_TOOLS and path:
            if path not in self._written_paths and self._stage == "interface_design":
                self._design_write_count += 1
            self._written_paths.add(path)
            self._cache_written_path(request, path)

    def _path_unlocked(self, path: str) -> bool:
        return self._validation_failed or path in self._failed_paths

    @staticmethod
    def _cache_read_summary(request: ToolCallRequest, path: str, offset: int, limit: int, result: ToolMessage | Any) -> None:
        if not isinstance(request.state, dict):
            return
        content = str(getattr(result, "content", "") or "")
        line_count = content.count("\n") + (1 if content else 0)
        request.state.setdefault("arc_read_summaries", {})[path] = (
            f"lines {offset}-{offset + limit - 1}; received {line_count} line(s), {len(content)} character(s)"
        )

    @staticmethod
    def _cache_written_path(request: ToolCallRequest, path: str) -> None:
        if isinstance(request.state, dict):
            written = request.state.setdefault("arc_written_paths", [])
            if path not in written:
                written.append(path)

    @staticmethod
    def _blocked(request: ToolCallRequest, message: str) -> ToolMessage:
        return ToolMessage(
            content=f"Error: ARC stage discipline: {message}",
            name=str(request.tool_call.get("name", "tool")),
            tool_call_id=str(request.tool_call.get("id", "")),
            status="error",
        )


def _discipline_path(args: dict[str, Any]) -> str:
    raw = str(args.get("file_path", "") or "").replace("\\", "/").strip()
    return raw if raw.startswith("/") else f"/{raw}" if raw else ""


def _as_nonnegative_int(value: Any, *, default: int) -> int:
    try:
        return max(0, int(value))
    except (TypeError, ValueError):
        return default


def _ranges_overlap(start: int, end: int, other_start: int, other_end: int) -> bool:
    return start < other_end and other_start < end


def _tool_result_failed(result: ToolMessage | Any) -> bool:
    if isinstance(result, ToolMessage) and result.status == "error":
        return True
    content = str(getattr(result, "content", "") or "")
    return "Exit Code: 0" not in content and ("Exit Code:" in content or content.lstrip().startswith("Error:"))


def _is_test_asset(path: str) -> bool:
    normalized = path.replace("\\", "/").lower()
    name = normalized.rsplit("/", 1)[-1]
    test_segments = ("/test/", "/tests/", "/__tests__/", "/e2e/", "/__mocks__/")
    test_names = (".test.", ".spec.", "playwright.config.", "vitest.config.", "jest.config.", "setup-tests.", "setuptests.")
    return any(segment in normalized for segment in test_segments) or any(marker in name for marker in test_names)

"""Select the small set of stage skills that ARC requires for one invocation."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any


SKILLS_SOURCE = "/skills/"
_AUTH_TERMS = (
    "login",
    "log in",
    "sign in",
    "register",
    "registration",
    "logout",
    "log out",
    "session",
    "authenticated",
    "authentication",
    "authorization",
    "current user",
    "account state",
)


def interface_design_skills(requirement_data: dict[str, Any]) -> list[str]:
    """Return the relevant design skill and, for leaf auth work, its cross-cutting skill."""

    names = [
        "non-leaf-ui-only-design"
        if requirement_data.get("children_ids")
        else "leaf-full-design"
    ]
    if not requirement_data.get("children_ids") and has_auth_context(requirement_data):
        names.append("auth-session-consistency")
    return available_skill_names(names)


def test_generation_skills(requirement_data: dict[str, Any]) -> list[str]:
    """Return test selection guidance plus auth guidance only when the node needs it."""

    names = ["leaf-test-layer-selection"]
    if has_auth_context(requirement_data):
        names.append("auth-session-consistency")
    return available_skill_names(names)


def implementation_skills(*, interface_contract: str, previous_failure_summary: str) -> list[str]:
    """Expose repair guidance only after a real failure, plus relevant auth guidance."""

    names: list[str] = []
    if previous_failure_summary.strip():
        names.append("tdd-test-failure-repair")
    if has_auth_context(interface_contract):
        names.append("auth-session-consistency")
    return available_skill_names(names)


def has_auth_context(value: object) -> bool:
    """Detect explicit authentication/session ownership without guessing from shell-only text."""

    if isinstance(value, str):
        text = value
    else:
        text = json.dumps(value, ensure_ascii=False, default=str)
    normalized = text.casefold()
    return any(term in normalized for term in _AUTH_TERMS)


def available_skill_names(names: list[str]) -> list[str]:
    """Keep declared skills in order and omit missing instruction files."""

    root = Path(__file__).resolve().parents[2] / "skills"
    return [name for name in dict.fromkeys(names) if (root / name / "SKILL.md").is_file()]

from __future__ import annotations

import inspect
import json
import os
import re
import time
from typing import Any, Awaitable, Callable

from pydantic import BaseModel

from agents.runtime.contracts import AgentRuntimeContext
from core.logging import format_json_for_log, log_to_logger


LogCallback = Callable[[str, str, str | None, str | None], Awaitable[None] | None]
DEFAULT_RECURSION_LIMIT = 5000


async def ainvoke_stage_agent(
    agent: Any,
    *,
    message: str,
    context: AgentRuntimeContext,
    thread_id: str,
    logger: Any | None = None,
    label: str = "",
    log_cb: LogCallback | None = None,
    stream: bool | None = None,
) -> dict[str, Any]:
    started_at = time.perf_counter()
    run_label = label or getattr(agent, "name", "") or context.phase or "stage-agent"
    log_to_logger(logger, "AGENT_CALL_START", label=run_label, thread_id=thread_id, body=message)
    await _emit_log(
        log_cb,
        run_label,
        f"agent call start: thread_id={thread_id}",
        node_id=context.node_id,
    )

    if _should_stream(stream):
        stream_payload = await _try_astream_stage_agent(
            agent,
            message=message,
            context=context,
            thread_id=thread_id,
            run_label=run_label,
            log_cb=log_cb,
            logger=logger,
        )
        if stream_payload is not None:
            duration_ms = (time.perf_counter() - started_at) * 1000.0
            log_to_logger(
                logger,
                "AGENT_CALL_END",
                label=run_label,
                thread_id=thread_id,
                body=f"duration_ms={duration_ms:.1f}\n{format_json_for_log(stream_payload)}",
            )
            await _emit_log(
                log_cb,
                run_label,
                f"agent call end: duration_ms={duration_ms:.1f}, payload={format_json_for_log(stream_payload)}",
                node_id=context.node_id,
            )
            return stream_payload

    result = await agent.ainvoke(
        {"messages": [{"role": "user", "content": message}]},
        context=context,
        config=build_agent_config(thread_id),
    )
    await _log_completed_tool_batches(log_cb, result, label=run_label, node_id=context.node_id)
    await _log_agent_trace(log_cb, result, label=run_label, thread_id=thread_id, node_id=context.node_id)
    payload = extract_payload(result)
    duration_ms = (time.perf_counter() - started_at) * 1000.0
    log_to_logger(
        logger,
        "AGENT_CALL_END",
        label=run_label,
        thread_id=thread_id,
        body=f"duration_ms={duration_ms:.1f}\n{format_json_for_log(payload)}",
    )
    await _emit_log(
        log_cb,
        run_label,
        f"agent call end: duration_ms={duration_ms:.1f}, payload={format_json_for_log(payload)}",
        node_id=context.node_id,
    )
    return payload


def extract_payload(result: dict[str, Any]) -> dict[str, Any]:
    structured = result.get("structured_response") if isinstance(result, dict) else None
    normalized = _normalize_payload_value(structured)
    if normalized is not None:
        return normalized

    final_text = _extract_final_message_text(result)
    parsed = parse_json_payload(final_text)
    if parsed is not None:
        return parsed
    return {"summary": final_text, "_raw_final_message": _stringify_final_message(result)}


def parse_json_payload(text: str) -> dict[str, Any] | None:
    current = (text or "").strip()
    for _ in range(3):
        if not current:
            return None
        next_string: str | None = None
        for candidate in _json_candidates(current):
            try:
                payload = json.loads(candidate)
            except json.JSONDecodeError:
                continue
            normalized = _normalize_payload_value(payload)
            if normalized is not None:
                return normalized
            if isinstance(payload, str) and payload.strip():
                next_string = payload.strip()
        if next_string is None:
            return None
        current = next_string
    return None


def _normalize_payload_value(value: Any) -> dict[str, Any] | None:
    if value is None:
        return None
    if isinstance(value, BaseModel):
        return value.model_dump()
    if hasattr(value, "model_dump"):
        dumped = value.model_dump()
        return dumped if isinstance(dumped, dict) else {"items": dumped}
    if isinstance(value, dict):
        return value
    if isinstance(value, list):
        return {"items": value}
    return None


def _extract_final_message_text(result: dict[str, Any]) -> str:
    if not isinstance(result, dict):
        return ""
    messages = result.get("messages") or []
    if not isinstance(messages, list) or not messages:
        return ""
    for message in reversed(messages):
        role = _message_role(message)
        if role in {"human", "tool"}:
            continue
        text = _message_content_text(message)
        if text:
            return text
    return ""


def _stringify_final_message(result: dict[str, Any]) -> str:
    if not isinstance(result, dict):
        return ""
    messages = result.get("messages") or []
    if not isinstance(messages, list) or not messages:
        return ""
    for message in reversed(messages):
        if _message_role(message) in {"human", "tool"}:
            continue
        return _truncate_text(_stringify_tool_args(_message_to_debug_payload(message)), max_chars=4000)
    return ""


def _message_to_debug_payload(message: Any) -> Any:
    if hasattr(message, "model_dump"):
        return message.model_dump()
    if isinstance(message, dict):
        return message
    return {
        "type": _message_role(message),
        "content": getattr(message, "content", None),
        "tool_calls": getattr(message, "tool_calls", None),
    }


async def _try_astream_stage_agent(
    agent: Any,
    *,
    message: str,
    context: AgentRuntimeContext,
    thread_id: str,
    run_label: str,
    log_cb: LogCallback | None,
    logger: Any | None,
) -> dict[str, Any] | None:
    if _should_use_sync_stream_v3():
        sync_payload = _try_stream_stage_agent_sync(
            agent,
            message=message,
            context=context,
            thread_id=thread_id,
            run_label=run_label,
            log_cb=log_cb,
            logger=logger,
        )
        if sync_payload is not None:
            return sync_payload

    if not hasattr(agent, "astream_events"):
        await _emit_log(log_cb, run_label, "agent streaming is unavailable; falling back to ainvoke.", node_id=context.node_id)
        return None

    await _emit_log(log_cb, run_label, "agent stream start.", node_id=context.node_id)
    final_state: dict[str, Any] | None = None
    try:
        event_stream = agent.astream_events(
            {"messages": [{"role": "user", "content": message}]},
            context=context,
            config=build_agent_config(thread_id),
            version=os.environ.get("ARC_AGENT_STREAM_VERSION", "v2"),
        )
        if inspect.isawaitable(event_stream):
            event_stream = await event_stream
        async for event in event_stream:
            maybe_state = await _log_stream_event(
                log_cb,
                event,
                label=run_label,
                node_id=context.node_id,
            )
            if isinstance(maybe_state, dict):
                final_state = maybe_state
    except Exception as exc:
        await _emit_log(
            log_cb,
            run_label,
            f"agent stream failed; falling back to ainvoke. error={exc}",
            status="warning",
            node_id=context.node_id,
        )
        log_to_logger(logger, "AGENT_STREAM_FALLBACK", label=run_label, thread_id=thread_id, body=str(exc))
        return None

    if final_state is None:
        await _emit_log(
            log_cb,
            run_label,
            "agent stream ended without final state; falling back to ainvoke.",
            status="warning",
            node_id=context.node_id,
        )
        return None

    await _log_agent_trace(log_cb, final_state, label=run_label, thread_id=thread_id, node_id=context.node_id)
    return extract_payload(final_state)


def _try_stream_stage_agent_sync(
    agent: Any,
    *,
    message: str,
    context: AgentRuntimeContext,
    thread_id: str,
    run_label: str,
    log_cb: LogCallback | None,
    logger: Any | None,
) -> dict[str, Any] | None:
    if not hasattr(agent, "stream_events"):
        return None
    try:
        stream = agent.stream_events(
            {"messages": [{"role": "user", "content": message}]},
            context=context,
            config=build_agent_config(thread_id),
            version=os.environ.get("ARC_AGENT_STREAM_VERSION", "v3"),
        )
        extensions = getattr(stream, "extensions", {}) or {}
        stream_names = [name for name in ("messages", "values", "subagents") if name in extensions]
        if not stream_names or not hasattr(stream, "interleave"):
            return None

        _emit_log_sync(log_cb, run_label, "agent stream start.", node_id=context.node_id)
        final_state: dict[str, Any] | None = None
        seen_message_count = 0
        for stream_name, item in stream.interleave(*stream_names):
            if stream_name == "messages":
                text = _typed_stream_item_text(item)
                if text:
                    _emit_log_sync(
                        log_cb,
                        run_label,
                        f"model> {_truncate_text(text, max_chars=1200)}",
                        node_id=context.node_id,
                    )
                continue

            if stream_name == "subagents":
                _log_subagent_stream_item_sync(log_cb, item, label=run_label, node_id=context.node_id)
                continue

            if stream_name == "values" and isinstance(item, dict):
                messages = item.get("messages")
                if isinstance(messages, list) and len(messages) > seen_message_count:
                    new_messages = messages[seen_message_count:]
                    seen_message_count = len(messages)
                    formatted = _format_message_trace(new_messages)
                    if formatted:
                        _emit_log_sync(
                            log_cb,
                            run_label,
                            f"stream messages:\n{formatted}",
                            node_id=context.node_id,
                        )
                if _is_agent_state_with_payload(item):
                    final_state = item

        latest = getattr(stream, "output", None)
        if isinstance(latest, dict) and _is_agent_state_with_payload(latest):
            final_state = latest
        if final_state is None:
            _emit_log_sync(
                log_cb,
                run_label,
                "agent stream ended without final state; falling back to ainvoke.",
                status="warning",
                node_id=context.node_id,
            )
            return None
        _log_agent_trace_sync(log_cb, final_state, label=run_label, thread_id=thread_id, node_id=context.node_id)
        return extract_payload(final_state)
    except Exception as exc:
        _emit_log_sync(
            log_cb,
            run_label,
            f"agent stream failed; falling back to ainvoke. error={exc}",
            status="warning",
            node_id=context.node_id,
        )
        log_to_logger(logger, "AGENT_STREAM_FALLBACK", label=run_label, thread_id=thread_id, body=str(exc))
        return None


async def _log_stream_event(
    log_cb: LogCallback | None,
    event: Any,
    *,
    label: str,
    node_id: str,
) -> dict[str, Any] | None:
    if not isinstance(event, dict):
        text = _typed_stream_item_text(event)
        if text:
            await _emit_log(log_cb, label, f"stream: {text}", node_id=node_id)
        return None

    event_name = str(event.get("event", "") or "")
    name = str(event.get("name", "") or "")
    data = event.get("data") if isinstance(event.get("data"), dict) else {}

    if event_name in {"on_chat_model_stream", "on_llm_stream"}:
        # The model is configured for non-streaming output. Ignore any provider
        # chunks that still arrive and render the complete response on *_end.
        return None

    if event_name in {"on_chat_model_end", "on_llm_end"}:
        text = _message_content_text(data.get("output"))
        if text:
            await _emit_log(log_cb, label, f"model-final> {_truncate_text(text, max_chars=2400)}", node_id=node_id)
        return None

    if event_name == "on_tool_start":
        tool_input = data.get("input")
        await _emit_log(
            log_cb,
            label,
            f"tool-call> {name or 'unknown'} args={_truncate_text(_stringify_tool_args(tool_input), max_chars=1000)}",
            node_id=node_id,
        )
        skill_name = _skill_name_from_read_call(name, tool_input)
        if skill_name:
            await _emit_log(log_cb, label, f"skill-loaded: {skill_name}", node_id=node_id)
        return None

    if event_name == "on_tool_end":
        await _emit_log(
            log_cb,
            label,
            f"tool-result> {name or 'unknown'} result={_truncate_text(_stringify_tool_args(data.get('output')), max_chars=2000)}",
            node_id=node_id,
        )
        return None

    if event_name in {"on_chain_end", "on_graph_end"}:
        output = data.get("output")
        if isinstance(output, dict) and _is_agent_state_with_payload(output):
            return output
    return None


def _skill_name_from_read_call(tool_name: str, tool_input: Any) -> str:
    """Return the selected skill name when the model reads its instruction file."""

    if tool_name != "read_file" or not isinstance(tool_input, dict):
        return ""
    file_path = str(tool_input.get("file_path") or tool_input.get("path") or "").strip().replace("\\", "/")
    match = re.fullmatch(r"/skills/([^/]+)/SKILL\.md", file_path)
    return match.group(1) if match else ""


def _is_agent_state_with_payload(state: dict[str, Any]) -> bool:
    structured = state.get("structured_response")
    if structured is not None:
        return True
    messages = state.get("messages")
    return isinstance(messages, list) and any(_message_role(message) not in {"human", "tool"} for message in messages)


async def _log_agent_trace(
    log_cb: LogCallback | None,
    result: dict[str, Any],
    *,
    label: str,
    thread_id: str,
    node_id: str,
) -> None:
    if not _should_log_full_agent_trace():
        return
    formatted = _format_message_trace(result.get("messages", []) if isinstance(result, dict) else [])
    if not formatted:
        await _emit_log(log_cb, label, f"agent trace is empty: thread_id={thread_id}", node_id=node_id)
        return
    await _emit_log(log_cb, label, f"agent trace: thread_id={thread_id}\n{formatted}", node_id=node_id)


async def _log_completed_tool_batches(
    log_cb: LogCallback | None,
    result: dict[str, Any],
    *,
    label: str,
    node_id: str,
) -> None:
    """Emit each completed tool-call batch from a non-streaming agent result."""

    messages = result.get("messages", []) if isinstance(result, dict) else []
    pending: list[dict[str, str]] = []
    for message in messages if isinstance(messages, list) else []:
        calls = _extract_tool_calls(message)
        if calls:
            await _emit_tool_batch(log_cb, label, pending, node_id=node_id)
            pending = [
                {
                    "id": str(call.get("id", "") or call.get("tool_call_id", "")),
                    "name": str(call.get("name", "") or call.get("tool_name", "") or "unknown"),
                    "args": _truncate_text(_stringify_tool_args(call.get("args")), max_chars=1200),
                    "result": "",
                }
                for call in calls
            ]
            continue

        if _message_role(message) != "tool" or not pending:
            continue
        tool_call_id = getattr(message, "tool_call_id", None)
        if tool_call_id is None and isinstance(message, dict):
            tool_call_id = message.get("tool_call_id")
        matched = next((item for item in pending if item["id"] and item["id"] == str(tool_call_id or "")), None)
        target = matched or next((item for item in pending if not item["result"]), None)
        if target is not None:
            target["result"] = _truncate_text(_message_content_text(message), max_chars=2000)
        if all(item["result"] for item in pending):
            await _emit_tool_batch(log_cb, label, pending, node_id=node_id)
            pending = []

    await _emit_tool_batch(log_cb, label, pending, node_id=node_id)


async def _emit_tool_batch(
    log_cb: LogCallback | None,
    label: str,
    tools: list[dict[str, str]],
    *,
    node_id: str,
) -> None:
    if not tools:
        return
    payload = {
        "tools": [
            {"name": item["name"], "args": item["args"], "result": item["result"] or "[no result returned]"}
            for item in tools
        ]
    }
    await _emit_log(log_cb, label, f"tool-batch> {json.dumps(payload, ensure_ascii=False)}", node_id=node_id)


def _log_agent_trace_sync(
    log_cb: LogCallback | None,
    result: dict[str, Any],
    *,
    label: str,
    thread_id: str,
    node_id: str,
) -> None:
    if not _should_log_full_agent_trace():
        return
    formatted = _format_message_trace(result.get("messages", []) if isinstance(result, dict) else [])
    if not formatted:
        return
    _emit_log_sync(log_cb, label, f"agent trace: thread_id={thread_id}\n{formatted}", node_id=node_id)


def _should_log_full_agent_trace() -> bool:
    return str(os.environ.get("ARC_DEBUG_AGENT_TRACE", "")).strip().lower() in {"1", "true", "yes", "on"}


def _format_message_trace(messages: list[Any]) -> str:
    if not isinstance(messages, list) or not messages:
        return ""
    blocks: list[str] = []
    for index, message in enumerate(messages, start=1):
        role = _message_role(message)
        if role == "human":
            continue
        lines = [f"[{index}] {role.upper()}"]
        tool_calls = _extract_tool_calls(message)
        if tool_calls:
            lines.append("tool_calls:")
            for tool_index, call in enumerate(tool_calls, start=1):
                tool_name = str(call.get("name", "") or call.get("tool_name", "") or "unknown")
                tool_id = str(call.get("id", "") or call.get("tool_call_id", "") or "-")
                tool_args = _truncate_text(_stringify_tool_args(call.get("args")), max_chars=1000)
                lines.append(f"  {tool_index}. {tool_name} id={tool_id}")
                if tool_args:
                    lines.append(f"     args: {tool_args}")
        tool_result_meta = _extract_tool_result_meta(message)
        if tool_result_meta:
            lines.append(tool_result_meta)
        content = _message_content_text(message)
        if content:
            lines.append("content:")
            lines.append(_indent_block(_truncate_text(content, max_chars=2400)))
        blocks.append("\n".join(lines))
    return "\n\n".join(blocks)


def _message_role(message: Any) -> str:
    role = getattr(message, "type", None) or getattr(message, "role", None)
    if role is None and isinstance(message, dict):
        role = message.get("type") or message.get("role")
    if isinstance(role, str) and role:
        return role
    cls_name = message.__class__.__name__.lower()
    if "tool" in cls_name:
        return "tool"
    if "human" in cls_name:
        return "human"
    if "ai" in cls_name or "assistant" in cls_name:
        return "assistant"
    return cls_name or "message"


def _extract_tool_calls(message: Any) -> list[dict[str, Any]]:
    calls = getattr(message, "tool_calls", None)
    if calls is None and isinstance(message, dict):
        calls = message.get("tool_calls")
    if not isinstance(calls, list):
        return []
    normalized: list[dict[str, Any]] = []
    for call in calls:
        if isinstance(call, dict):
            normalized.append(call)
            continue
        normalized.append(
            {
                "name": getattr(call, "name", ""),
                "id": getattr(call, "id", ""),
                "args": getattr(call, "args", {}),
            }
        )
    return normalized


def _extract_tool_result_meta(message: Any) -> str:
    if _message_role(message) != "tool":
        return ""
    tool_name = getattr(message, "name", None)
    if tool_name is None and isinstance(message, dict):
        tool_name = message.get("name")
    tool_call_id = getattr(message, "tool_call_id", None)
    if tool_call_id is None and isinstance(message, dict):
        tool_call_id = message.get("tool_call_id")
    parts = ["tool_result:"]
    if tool_name:
        parts.append(f"name={tool_name}")
    if tool_call_id:
        parts.append(f"id={tool_call_id}")
    return " ".join(parts)


def _message_content_text(message: Any) -> str:
    content = getattr(message, "content", None)
    if content is None and isinstance(message, dict):
        content = message.get("content")
    return _content_text(content)


def _content_text(content: Any) -> str:
    if isinstance(content, str):
        return content.strip()
    if isinstance(content, list):
        parts = [_content_text(item) for item in content]
        return "\n".join(part for part in parts if part).strip()
    if isinstance(content, dict):
        for key in ("text", "content", "output_text"):
            value = content.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
        parsed = content.get("parsed")
        if isinstance(parsed, (dict, list)):
            return json.dumps(parsed, ensure_ascii=False)
        if isinstance(parsed, str) and parsed.strip():
            return parsed.strip()
        nested_parts = [_content_text(value) for value in content.values()]
        return "\n".join(part for part in nested_parts if part).strip()
    if content is None:
        return ""
    text = getattr(content, "text", None)
    if isinstance(text, str) and text.strip():
        return text.strip()
    nested = getattr(content, "content", None)
    if nested is not None:
        return _content_text(nested)
    return str(content).strip()


def _typed_stream_item_text(item: Any) -> str:
    if isinstance(item, tuple) and item:
        parts = [_typed_stream_item_text(part) for part in item]
        return " ".join(part for part in parts if part).strip()
    text = getattr(item, "text", None)
    if isinstance(text, str) and text.strip():
        return text.strip()
    content = _message_content_text(item)
    if content:
        return content
    name = getattr(item, "name", None)
    status = getattr(item, "status", None)
    if name or status:
        return f"name={name or '-'} status={status or '-'}"
    return ""


def _log_subagent_stream_item_sync(
    log_cb: LogCallback | None,
    item: Any,
    *,
    label: str,
    node_id: str,
) -> None:
    name = getattr(item, "name", "") or "subagent"
    status = getattr(item, "status", "") or ""
    _emit_log_sync(log_cb, label, f"subagent> {name} status={status or '-'}", node_id=node_id)
    messages = getattr(item, "messages", None)
    if messages:
        formatted = _format_message_trace(list(messages))
        if formatted:
            _emit_log_sync(log_cb, label, f"subagent messages ({name}):\n{formatted}", node_id=node_id)
    output = getattr(item, "output", None)
    if output:
        _emit_log_sync(
            log_cb,
            label,
            f"subagent output ({name}): {_truncate_text(_stringify_tool_args(output), max_chars=2000)}",
            node_id=node_id,
        )


def _stringify_tool_args(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        return value.strip()
    try:
        return json.dumps(value, ensure_ascii=False, default=str)
    except TypeError:
        return repr(value)


def _truncate_text(text: str, *, max_chars: int) -> str:
    normalized = (text or "").strip()
    if len(normalized) <= max_chars:
        return normalized
    return normalized[: max_chars - 18].rstrip() + "\n...[truncated]"


def _indent_block(text: str, prefix: str = "  ") -> str:
    return "\n".join(prefix + line for line in text.splitlines()) if text else prefix


async def _emit_log(
    log_cb: LogCallback | None,
    agent_name: str,
    message: str,
    *,
    status: str | None = None,
    node_id: str | None = None,
) -> None:
    if log_cb is None:
        return
    result = log_cb(agent_name, message, status, node_id)
    if inspect.isawaitable(result):
        await result


def _emit_log_sync(
    log_cb: LogCallback | None,
    agent_name: str,
    message: str,
    *,
    status: str | None = None,
    node_id: str | None = None,
) -> None:
    if log_cb is None:
        return
    result = log_cb(agent_name, message, status, node_id)
    if not inspect.isawaitable(result):
        return
    try:
        loop = None
        try:
            import asyncio

            loop = asyncio.get_running_loop()
        except RuntimeError:
            loop = None
        if loop is not None and loop.is_running():
            loop.create_task(result)
            return
        close = getattr(result, "close", None)
        if callable(close):
            close()
    except Exception:
        return


def _should_stream(stream: bool | None) -> bool:
    if stream is not None:
        return stream
    return True


def _should_use_sync_stream_v3() -> bool:
    return False


def build_agent_config(thread_id: str) -> dict[str, Any]:
    return {
        "configurable": {"thread_id": thread_id},
        "recursion_limit": DEFAULT_RECURSION_LIMIT,
    }


def _json_candidates(text: str) -> list[str]:
    candidates: list[str] = []

    def add(candidate: str) -> None:
        stripped = candidate.strip()
        if stripped and stripped not in candidates:
            candidates.append(stripped)

    add(text)
    for match in re.findall(r"```(?:json)?\s*(.*?)```", text, flags=re.DOTALL | re.IGNORECASE):
        add(match)
    for opener, closer in (("{", "}"), ("[", "]")):
        start = text.find(opener)
        end = text.rfind(closer)
        if start != -1 and end != -1 and end > start:
            add(text[start : end + 1])
    return candidates

