"""Locate the capability library that ships inside the agent."""

from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path

LIBRARY_ROOT = Path(__file__).resolve().parent / "packs"

#: The file every capability pack carries. It is deliberately a file the pack
#: itself needs in order to run, not a build artefact: the packaging step strips
#: ``MANIFEST.json`` (it is build output), so the presence check must not depend
#: on it.
MARKER = "package.json"


def library_path(pack: str) -> Path:
    return LIBRARY_ROOT / pack


def pack_exists(pack: str) -> bool:
    return (library_path(pack) / MARKER).is_file()


@lru_cache(maxsize=None)
def pack_manifest(pack: str) -> dict:
    path = library_path(pack) / "MANIFEST.json"
    if not path.is_file():
        return {}
    return json.loads(path.read_text(encoding="utf-8"))


def available_packs() -> list[str]:
    if not LIBRARY_ROOT.is_dir():
        return []
    return sorted(path.name for path in LIBRARY_ROOT.iterdir() if (path / MARKER).is_file())

from __future__ import annotations

import json
import os
from typing import Any


def section(title: str, lines: list[str]) -> str:
    return "\n".join([f"### {title}", *(f"- {line}" for line in lines)])


def json_block(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, indent=2, default=str)


