def task_context_block(
    *,
    node_id: str,
    dynamic_context: str,
    requirement_data: dict[str, Any],
    extra_sections: list[str] | None = None,
) -> str:
    sections = [
        f"### Current Node\n`{node_id}`",
        "### Dynamic Context",
        dynamic_context.strip(),
        "### Requirement Snapshot",
        f"```json\n{json_block(requirement_data)}\n```",
