"""Rewrite the document-stated literals inside a copied capability pack.

A capability pack is written against *some* wording: the button it calls "New
blank workbook", the workbook it seeds as "Q3 Sales". The requirement document
states its own wording for the same observable strings. This module turns the
pair of them into a substitution map and applies it to the emitted tree.

Two constraints keep the rewrite honest:

* only literals that a *map entry* or a *seed slot* has vouched for are ever
  rewritten, so a global rename cannot leak into unrelated code (renaming the
  seeded worksheet ``Sheet1`` everywhere, for instance, would break the
  requirement that a brand-new workbook's first worksheet is called ``Sheet1``);
* replacement is anchored to whole quoted literals and whole JSX text nodes, so
  ``Sort`` never corrupts ``Sort range`` or the ``SortRange`` identifier.
"""

from __future__ import annotations

import json
import re
from dataclasses import dataclass, field
from pathlib import Path

from synth.appspec import AppSpec

MAPS_DIR = Path(__file__).resolve().parent.parent / "maps"

#: File types the rewriter inspects.
TEXT_SUFFIXES = {
    ".js",
    ".jsx",
    ".mjs",
    ".cjs",
    ".ts",
    ".tsx",
    ".json",
    ".css",
    ".html",
    ".md",
    ".txt",
    ".yml",
    ".yaml",
}

#: Lockfiles are byte-stable input to ``npm install``; never touch them.
SKIP_NAMES = {"package-lock.json", "npm-shrinkwrap.json", "MANIFEST.json"}

#: One quoted string literal, honouring backslash escapes.
QUOTE_PATTERNS = {
    quote: re.compile(re.escape(quote) + r"((?:\\.|[^" + re.escape(quote) + r"\\\n])*)" + re.escape(quote))
    for quote in ("'", '"', "`")
}

#: A JSX text node: everything between ``>`` and ``<`` that is not an expression.
JSX_TEXT = re.compile(r">([^<>{}]*?)<")


@dataclass(slots=True)
class SubstitutionStats:
    total: int = 0
    files_changed: int = 0
    per_literal: dict[str, int] = field(default_factory=dict)

    def record(self, literal: str, count: int) -> None:
        if count:
            self.total += count
            self.per_literal[literal] = self.per_literal.get(literal, 0) + count

    def as_dict(self) -> dict:
        return {
            "occurrences": self.total,
            "files_changed": self.files_changed,
            "per_literal": dict(sorted(self.per_literal.items())),
        }


def load_seed_defaults(pack: str) -> dict:
    path = MAPS_DIR / f"{pack}.seed.json"
    if not path.is_file():
        return {}
    return json.loads(path.read_text(encoding="utf-8"))


def build_substitutions(spec: AppSpec) -> dict[str, str]:
    """Every literal the document overrides, mapped to the document's wording."""
    from synth.seed.collab import seed_substitutions

    mapping = seed_substitutions(spec.seed or {}, load_seed_defaults(spec.pack))

    # Catalog-derived overrides win: they are the strings the evaluation can
    # actually observe through the accessible tree.
    mapping.update(spec.substitutions)
    mapping.pop("", None)
    return mapping


def substitute_text(text: str, mapping: dict[str, str]) -> tuple[str, dict[str, int]]:
    """Apply ``mapping`` to whole quoted literals and JSX text nodes."""
    counts: dict[str, int] = {}

    def bump(literal: str) -> None:
        counts[literal] = counts.get(literal, 0) + 1

    for quote, pattern in QUOTE_PATTERNS.items():

        def replace(match: re.Match[str], quote: str = quote) -> str:
            body = match.group(1)
            replacement = mapping.get(body)
            if replacement is None:
                return match.group(0)
            bump(body)
            escaped = replacement.replace("\\", "\\\\")
            if quote == "`":
                escaped = escaped.replace("`", "\\`").replace("${", "\\${")
            else:
                escaped = escaped.replace(quote, "\\" + quote)
            return f"{quote}{escaped}{quote}"

        text = pattern.sub(replace, text)

    def replace_jsx(match: re.Match[str]) -> str:
        inner = match.group(1)
        stripped = inner.strip()
        replacement = mapping.get(stripped)
        if replacement is None:
            return match.group(0)
        bump(stripped)
        return ">" + inner.replace(stripped, replacement) + "<"

    text = JSX_TEXT.sub(replace_jsx, text)
    return text, counts


def substitute_tree(root: Path, mapping: dict[str, str]) -> SubstitutionStats:
    stats = SubstitutionStats()
    if not mapping:
        return stats
    for path in sorted(root.rglob("*")):
        if not path.is_file():
            continue
        if path.suffix.lower() not in TEXT_SUFFIXES or path.name in SKIP_NAMES:
            continue
        raw = path.read_bytes()
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError:
            continue
        rewritten, counts = substitute_text(text, mapping)
        if not counts:
            continue
        path.write_text(rewritten, encoding="utf-8")
        stats.files_changed += 1
        for literal, count in counts.items():
            stats.record(literal, count)
    return stats

"""Structural self-check on an emitted application.

The evaluator's contract is fixed (``prebuilt/CONVENTIONS-v2-web-runtime.md``):
``npm install`` in ``backend/`` then ``frontend/``, ``npm run build`` in
``frontend/`` producing ``frontend/dist/index.html``, ``npm run db:prepare:e2e``
and ``npm run start`` in ``backend/``, one port serving the SPA and ``/api/*``.

Emission copies a capability pack that already satisfies the contract, so this
check should never fire. It exists because it is the difference between "the
agent emitted something plausible" and "the agent emitted something the
evaluator can run": when it fires, the caller hands the document to the ARC
pipeline instead of submitting a tree that cannot start.
"""

from __future__ import annotations

import json
from pathlib import Path

#: ``(relative path, what it is for)`` — the minimum tree the evaluator needs.
REQUIRED_FILES: tuple[tuple[str, str], ...] = (
    ("backend/package.json", "backend manifest"),
    ("frontend/package.json", "frontend manifest"),
    ("frontend/index.html", "SPA entry document"),
)

#: npm scripts each manifest must define.
REQUIRED_SCRIPTS: tuple[tuple[str, str], ...] = (
    ("backend", "start"),
    ("frontend", "build"),
)


def check_tree(output_dir: Path) -> list[str]:
    """Return the problems that would stop the evaluator running this tree."""
    problems: list[str] = []

    for relative, label in REQUIRED_FILES:
        if not (output_dir / relative).is_file():
            problems.append(f"missing {label} ({relative})")

    has_server = any(
        (output_dir / "backend" / "src" / name).is_file()
        for name in ("server.js", "app.js", "index.js", "main.js")
    )
    if not has_server:
        problems.append("no backend server entry point under backend/src/")

    has_spa = any((output_dir / "frontend" / "src" / name).is_file() for name in ("App.jsx", "App.js", "main.jsx", "main.js"))
    if not has_spa:
        problems.append("no frontend application entry under frontend/src/")

    for package, script in REQUIRED_SCRIPTS:
        manifest = output_dir / package / "package.json"
        if not manifest.is_file():
            continue
        try:
            data = json.loads(manifest.read_text(encoding="utf-8"))
        except ValueError as error:
            problems.append(f"{package}/package.json is not valid JSON ({error})")
            continue
        if script not in (data.get("scripts") or {}):
            problems.append(f"{package}/package.json defines no '{script}' script")

    if not (output_dir / "package.json").is_file():
        problems.append("missing root package.json")

    return problems


def check_seed(spec, output_dir: Path) -> list[str]:
    """Confirm the generated seed actually carries what the document declared."""
    from synth.emit.seedjs import seed_coverage

    coverage = seed_coverage(spec, output_dir)
    problems: list[str] = []
    if spec.pack == "spreadsheet":
        seed = spec.seed or {}
        cells = seed.get("cells") or {}
        if cells:
            seed_module = output_dir / "backend" / "src" / "lib" / "seed.js"
            if not seed_module.is_file():
                problems.append("the spreadsheet seed module was not generated")
            else:
                text = seed_module.read_text(encoding="utf-8")
                missing = [name for name, value in cells.items() if f"{name}: " not in text]
                if missing:
                    problems.append(f"the generated seed omits {len(missing)} declared cell(s): {missing[:6]}")
    return problems

"""Extract the observable UI vocabulary from requirement prose.

The evaluation can only observe what the browser exposes: accessible names,
field labels, dialog names, option text and message wording. Those strings are
written out verbatim in the requirement descriptions, in quotes. Each capability
pack ships a *string map* that says, for every literal the library sources
contain, where in the document the same string is stated. The emitter then
rewrites the library literal to whatever the document actually says.

That indirection is the difference between compiling and copying: change the
document and the emitted application changes with it.
"""

from __future__ import annotations

import json
import re
from dataclasses import dataclass
from pathlib import Path

from synth.reqs.model import RequirementSet
from synth.reqs.quotes import find_after, find_before, normalise, squeeze

MAPS_DIR = Path(__file__).resolve().parent.parent / "maps"


@dataclass(slots=True)
class CatalogEntry:
    """One library literal and the place the document states it."""

    key: str
    lib: str
    req: str | None = None
    after: str | None = None
    before: str | None = None
    kind: str = "double"
    occurrence: int = 0
    scope: str = "req"  # "req" (that requirement only) or "document"
    pattern: str | None = None
    template: str | None = None
    optional: bool = False

    @classmethod
    def from_dict(cls, raw: dict) -> "CatalogEntry":
        return cls(
            key=str(raw["key"]),
            lib=str(raw["lib"]),
            req=raw.get("req"),
            after=raw.get("after"),
            before=raw.get("before"),
            kind=str(raw.get("kind", "double")),
            occurrence=int(raw.get("occurrence", 0)),
            scope=str(raw.get("scope", "req")),
            pattern=raw.get("pattern"),
            template=raw.get("template"),
            optional=bool(raw.get("optional", False)),
        )


@dataclass(slots=True)
class CatalogResult:
    values: dict[str, str]
    substitutions: dict[str, str]
    warnings: list[str]
    resolved: dict[str, str]
    fallbacks: list[str]


def load_string_map(pack: str) -> list[CatalogEntry]:
    path = MAPS_DIR / f"{pack}.json"
    if not path.is_file():
        return []
    raw = json.loads(path.read_text(encoding="utf-8"))
    return [CatalogEntry.from_dict(item) for item in raw.get("entries", [])]


def _document_text(requirement_set: RequirementSet) -> str:
    chunks = []
    for node in requirement_set.root.walk():
        chunks.append(squeeze(normalise(node.description)))
    for node in requirement_set.root.walk():
        for scenario in node.scenarios:
            for step in scenario.steps:
                chunks.append(step.text)
    return " ".join(chunk for chunk in chunks if chunk)


def _node_text(requirement_set: RequirementSet, req_id: str) -> str | None:
    """The text a map entry searches, or ``None`` to fall back to the document.

    A map entry names the requirement that states a string, but the entry must
    survive the document's identifiers being relabelled: when the cited node is
    absent the search widens to the whole document rather than silently falling
    back to the capability pack's own wording.
    """
    node = requirement_set.by_id(req_id)
    if node is None:
        return None
    parts = [squeeze(normalise(node.description))]
    for scenario in node.scenarios:
        parts.append(squeeze(normalise(scenario.name)))
        for step in scenario.steps:
            parts.append(step.text)
    if node.parent is not None:
        parts.append(squeeze(normalise(node.parent.description)))
        ancestors = node.parent.parent
        if ancestors is not None:
            parts.append(squeeze(normalise(ancestors.description)))
    return " ".join(part for part in parts if part)


def _document_fallback(document: str, entry: "CatalogEntry") -> str | None:
    """Recover an entry whose cited requirement is absent from the document.

    Widening the search to the whole document is only safe when the anchor is
    unambiguous: if the phrase occurs more than once there is no way to tell
    which value the entry meant, so the capability pack's own wording is kept
    instead of guessing.
    """
    anchor = entry.after or entry.before
    if not anchor:
        return None
    if len(re.findall(re.escape(anchor), document, re.IGNORECASE)) != 1:
        return None
    if entry.before:
        return find_before(document, entry.before, kind=entry.kind, occurrence=entry.occurrence)
    return find_after(document, entry.after, kind=entry.kind, occurrence=entry.occurrence)


def validate_proposals(
    requirement_set: RequirementSet,
    proposals: list[dict],
) -> tuple[dict[str, str], dict[str, str], list[str], list[str]]:
    """Read proposed bindings back out of the document.

    A proposal is a claim of the form "the pack's literal ``lib`` is stated in
    the document immediately after ``after``". The claim is checked by performing
    the read: anything that does not reproduce ``lib`` exactly is rejected, which
    is what makes a model-generated map safe to consume.
    """
    entries: list[CatalogEntry] = []
    for index, proposal in enumerate(proposals):
        raw = {**proposal, "key": f"proposed-{index}"}
        raw.pop("before", None)
        try:
            entries.append(CatalogEntry.from_dict(raw))
        except (KeyError, TypeError, ValueError):
            continue
    if not entries:
        return {}, {}, [], []

    result = extract_catalog(requirement_set, entries)
    values: dict[str, str] = {}
    substitutions: dict[str, str] = {}
    accepted: list[str] = []
    rejected: list[str] = []
    for entry in entries:
        if result.values.get(entry.key) == entry.lib:
            values[entry.key] = entry.lib
            substitutions[entry.lib] = entry.lib
            accepted.append(entry.lib)
        else:
            rejected.append(entry.lib)
    return values, substitutions, accepted, rejected


def document_text(requirement_set: RequirementSet) -> str:
    """Every quoted-string-bearing sentence in the document, as one string."""
    return _document_text(requirement_set)


def requirement_ids(requirement_set: RequirementSet) -> list[str]:
    return [node.id for node in requirement_set.root.walk()]


def unbound_literals(result: CatalogResult, entries: list[CatalogEntry]) -> list[str]:
    """The pack literals the map cites but the document did not yield."""
    missed = set(result.fallbacks)
    return [entry.lib for entry in entries if entry.key in missed]


def extract_catalog(requirement_set: RequirementSet, entries: list[CatalogEntry]) -> CatalogResult:
    document = _document_text(requirement_set)
    values: dict[str, str] = {}
    substitutions: dict[str, str] = {}
    resolved: dict[str, str] = {}
    warnings: list[str] = []
    fallbacks: list[str] = []

    for entry in entries:
        value: str | None = None

        if entry.pattern:
            text = (_node_text(requirement_set, entry.req) if entry.req else None) or document
            if text:
                match = re.search(entry.pattern, text)
                if match:
                    value = entry.template.format(*match.groups()) if entry.template else match.group(0)

        if value is None:
            text = _node_text(requirement_set, entry.req) if (entry.req and entry.scope == "req") else document
            if text:
                if entry.before:
                    value = find_before(text, entry.before, kind=entry.kind, occurrence=entry.occurrence)
                elif entry.after:
                    value = find_after(
                        text,
                        entry.after,
                        kind=entry.kind,
                        occurrence=entry.occurrence,
                        window=300,
                    )
            if value is None and entry.req and entry.scope == "req":
                value = _document_fallback(document, entry)

        if value is None:
            if not entry.optional:
                warnings.append(f"catalog[{entry.key}]: not stated in the document; kept library default {entry.lib!r}")
            fallbacks.append(entry.key)
            continue

        values[entry.key] = value
        resolved[entry.key] = value
        if value != entry.lib:
            substitutions[entry.lib] = value

    return CatalogResult(
        values=values,
        substitutions=substitutions,
        warnings=warnings,
        resolved=resolved,
        fallbacks=fallbacks,
    )

from __future__ import annotations

import os
from dataclasses import dataclass
from typing import Any, Literal, NoReturn

import httpx
from openai import APIConnectionError, APIError, APIStatusError, APITimeoutError, OpenAIError
from langchain_openai import ChatOpenAI
from pydantic import PrivateAttr

from agents.model.compatible_openai import CompatibleChatOpenAI


OpenAIAPIMode = Literal["responses", "chat_completions"]
_TRUTHY = {"1", "true", "yes", "on", "responses", "response", "responses_api"}
_FALSY = {"0", "false", "no", "off", "chat", "chat_completion", "chat_completions", "chat/completions"}


@dataclass(frozen=True)
class OpenAIAdapterConfig:
    model_name: str
    api_mode: OpenAIAPIMode
    base_url: str = ""
    api_key: str = ""
    sse_text_compat: bool = False


class ARCModelAPIError(RuntimeError):
    """Normalized exception for OpenAI-compatible model API failures."""

    def __init__(
        self,
        message: str,
        *,
        api_mode: OpenAIAPIMode,
        model: str,
        status_code: int | None = None,
        error_type: str = "",
        original: BaseException | None = None,
    ) -> None:
        super().__init__(message)
        self.api_mode = api_mode
        self.model = model
        self.status_code = status_code
        self.error_type = error_type
        self.original = original


class ARCChatOpenAI(ChatOpenAI):
    """ChatOpenAI with ARC-level API error normalization."""

    _arc_api_mode: OpenAIAPIMode = PrivateAttr(default="chat_completions")
    _arc_model_name: str = PrivateAttr(default="")

    def __init__(self, *args: Any, arc_api_mode: OpenAIAPIMode, arc_model_name: str, **kwargs: Any) -> None:
        super().__init__(*args, **kwargs)
        self._arc_api_mode = arc_api_mode
        self._arc_model_name = arc_model_name

    async def _agenerate(self, messages, stop=None, run_manager=None, **kwargs):  # type: ignore[override]
        try:
            return await super()._agenerate(messages, stop=stop, run_manager=run_manager, **kwargs)
        except Exception as exc:
            _raise_model_api_exception(exc, api_mode=self._arc_api_mode, model=self._arc_model_name)

    def _generate(self, messages, stop=None, run_manager=None, **kwargs):  # type: ignore[override]
        try:
            return super()._generate(messages, stop=stop, run_manager=run_manager, **kwargs)
        except Exception as exc:
            _raise_model_api_exception(exc, api_mode=self._arc_api_mode, model=self._arc_model_name)


class ARCCompatibleChatOpenAI(CompatibleChatOpenAI):
    """Responses-compatible ChatOpenAI with ARC-level API error normalization."""

    _arc_api_mode: OpenAIAPIMode = PrivateAttr(default="responses")
    _arc_model_name: str = PrivateAttr(default="")

    def __init__(self, *args: Any, arc_api_mode: OpenAIAPIMode, arc_model_name: str, **kwargs: Any) -> None:
        super().__init__(*args, **kwargs)
        self._arc_api_mode = arc_api_mode
        self._arc_model_name = arc_model_name

    async def _agenerate(self, messages, stop=None, run_manager=None, **kwargs):  # type: ignore[override]
        try:
            return await super()._agenerate(messages, stop=stop, run_manager=run_manager, **kwargs)
        except Exception as exc:
            _raise_model_api_exception(exc, api_mode=self._arc_api_mode, model=self._arc_model_name)

    def _generate(self, messages, stop=None, run_manager=None, **kwargs):  # type: ignore[override]
        try:
            return super()._generate(messages, stop=stop, run_manager=run_manager, **kwargs)
        except Exception as exc:
            _raise_model_api_exception(exc, api_mode=self._arc_api_mode, model=self._arc_model_name)


def build_openai_chat_model(
    model_name: str,
    *,
    api_mode: str | None = None,
    base_url: str | None = None,
    api_key: str | None = None,
) -> ChatOpenAI:
    config = resolve_openai_adapter_config(
        model_name=model_name,
        api_mode=api_mode,
        base_url=base_url,
        api_key=api_key,
    )
    kwargs: dict[str, Any] = {
        "model": config.model_name,
        "disable_streaming": True,
        "stream_usage": False,
        "use_responses_api": config.api_mode == "responses",
        "output_version": "responses/v1" if config.api_mode == "responses" else "v0",
        "arc_api_mode": config.api_mode,
        "arc_model_name": config.model_name,
    }
    if config.base_url:
        kwargs["base_url"] = config.base_url
    if config.api_key:
        kwargs["api_key"] = config.api_key

    model_class = ARCCompatibleChatOpenAI if config.sse_text_compat else ARCChatOpenAI
    return model_class(**kwargs)


def resolve_openai_adapter_config(
    *,
    model_name: str,
    api_mode: str | None = None,
    base_url: str | None = None,
    api_key: str | None = None,
) -> OpenAIAdapterConfig:
    resolved_base_url = (base_url if base_url is not None else _get_openai_base_url()).strip()
    resolved_api_key = (api_key if api_key is not None else os.getenv("OPENAI_API_KEY", "")).strip()
    resolved_mode = resolve_openai_api_mode(api_mode)
    return OpenAIAdapterConfig(
        model_name=model_name,
        api_mode=resolved_mode,
        base_url=resolved_base_url,
        api_key=resolved_api_key,
        sse_text_compat=_should_use_sse_text_compat(resolved_base_url, resolved_mode),
    )


def resolve_openai_api_mode(api_mode: str | None = None) -> OpenAIAPIMode:
    requested = str(api_mode or os.getenv("ARC_OPENAI_API_MODE", "")).strip().lower()
    if not requested:
        return "chat_completions"
    if requested in _TRUTHY or requested in {"responses"}:
        return "responses"
    if requested in _FALSY or requested in {"chat_completions", "chat"}:
        return "chat_completions"
    raise ValueError(
        "Invalid OpenAI API mode. Use `responses` or `chat_completions` "
        "(aliases: true/false for responses, chat for chat_completions)."
    )


def should_disable_streaming_for_openai_mode(api_mode: str | None = None) -> bool:
    if resolve_openai_api_mode(api_mode) != "responses":
        return False
    force = os.environ.get("ARC_AGENT_FORCE_RESPONSES_STREAM", "").strip().lower()
    if force in {"1", "true", "yes", "on"}:
        return False
    base_url = _get_openai_base_url()
    if not base_url:
        return False
    return not _is_official_openai_base_url(base_url)


def normalize_model_api_exception(exc: Exception, *, api_mode: OpenAIAPIMode, model: str) -> Exception:
    """Return ARC's normalized API exception when `exc` is model-provider related."""

    return _wrap_model_api_exception(exc, api_mode=api_mode, model=model)


def _raise_model_api_exception(exc: Exception, *, api_mode: OpenAIAPIMode, model: str) -> NoReturn:
    wrapped = _wrap_model_api_exception(exc, api_mode=api_mode, model=model)
    if wrapped is exc:
        raise exc
    raise wrapped from exc


def _wrap_model_api_exception(exc: Exception, *, api_mode: OpenAIAPIMode, model: str) -> Exception:
    if isinstance(exc, ARCModelAPIError):
        return exc
    if not _is_model_api_exception(exc):
        return exc
    status_code = getattr(exc, "status_code", None)
    error_type = _extract_error_type(exc)
    message = _format_model_api_error_message(
        exc,
        api_mode=api_mode,
        model=model,
        status_code=status_code,
        error_type=error_type,
    )
    return ARCModelAPIError(
        message,
        api_mode=api_mode,
        model=model,
        status_code=status_code if isinstance(status_code, int) else None,
        error_type=error_type,
        original=exc,
    )


def _is_model_api_exception(exc: Exception) -> bool:
    return isinstance(
        exc,
        (
            OpenAIError,
            APIError,
            APIStatusError,
            APIConnectionError,
            APITimeoutError,
            httpx.HTTPError,
        ),
    )


def _format_model_api_error_message(
    exc: Exception,
    *,
    api_mode: OpenAIAPIMode,
    model: str,
    status_code: Any,
    error_type: str,
) -> str:
    parts = [
        f"Model API request failed using `{api_mode}` mode",
        f"model={model or '<unknown>'}",
    ]
    if status_code:
        parts.append(f"status={status_code}")
    if error_type:
        parts.append(f"type={error_type}")
    parts.append(f"error={_short_error_text(exc)}")
    if api_mode == "responses":
        parts.append("If the provider does not support Responses API, set ARC_OPENAI_API_MODE=chat_completions.")
    return "; ".join(parts)


def _extract_error_type(exc: Exception) -> str:
    body = getattr(exc, "body", None)
    if isinstance(body, dict):
        error = body.get("error")
        if isinstance(error, dict):
            return str(error.get("type") or error.get("code") or "").strip()
        return str(body.get("type") or body.get("code") or "").strip()
    return type(exc).__name__


def _short_error_text(exc: Exception, limit: int = 800) -> str:
    text = str(exc).replace("\r", " ").replace("\n", " ").strip()
    if len(text) <= limit:
        return text
    return text[:limit].rstrip() + "... [truncated]"


def _should_use_sse_text_compat(base_url: str, api_mode: OpenAIAPIMode) -> bool:
    override = os.getenv("ARC_OPENAI_SSE_TEXT_COMPAT", "").strip().lower()
    if override in {"1", "true", "yes", "on"}:
        return True
    if override in {"0", "false", "no", "off"}:
        return False
    return bool(base_url and api_mode == "responses" and not _is_official_openai_base_url(base_url))


def _get_openai_base_url() -> str:
    return os.getenv("OPENAI_API_BASE", "").strip() or os.getenv("OPENAI_BASE_URL", "").strip()


def _is_official_openai_base_url(base_url: str) -> bool:
    try:
        from urllib.parse import urlparse

        host = urlparse(base_url).hostname or ""
    except Exception:
        host = ""
    return host == "api.openai.com" or host.endswith(".openai.com")

from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any

from core.config import get_workspace_root


def load_node_session(node_id: str) -> dict[str, Any]:
    path = _node_session_path(node_id)
    if not path.exists():
        return {}
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}


def save_node_session(node_id: str, payload: dict[str, Any]) -> None:
    path = _node_session_path(node_id)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp_path = path.with_suffix(path.suffix + ".tmp")
    tmp_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    tmp_path.replace(path)


def merge_node_session(node_id: str, patch: dict[str, Any]) -> dict[str, Any]:
    current = load_node_session(node_id)
    merged = _deep_merge_dict(current, patch)
    save_node_session(node_id, merged)
    return merged


def _node_session_path(node_id: str) -> Path:
    safe_node_id = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(node_id or "").strip()) or "node"
    return Path(get_workspace_root()) / ".arc" / "node_sessions" / f"{safe_node_id}.json"


def _deep_merge_dict(base: dict[str, Any], patch: dict[str, Any]) -> dict[str, Any]:
    result = dict(base)
    for key, value in patch.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = _deep_merge_dict(result[key], value)
        else:
            result[key] = value
    return result

